contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount == 0);

        uint beforeContractBalance = address(c).balance;
        uint beforeTesterBalance = address(this).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;
        bool reverted = false;

        uint afterContractBalance = address(c).balance;
        uint afterTesterBalance = address(this).balance;

        assert(
            !reverted &&
            afterContractBalance == beforeContractBalance &&
            afterTesterBalance == beforeTesterBalance
        );
    }

    receive() external payable {}
}

