// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        amount = 0;
        uint beforeContractBalance = address(c).balance;
        uint beforeTesterBalance = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        bool reverted = false;
        uint afterContractBalance = address(c).balance;
        uint afterTesterBalance = address(this).balance;
        assertTrue(!reverted &&
            afterContractBalance == beforeContractBalance &&
            afterTesterBalance == beforeTesterBalance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
